// Logic component types
export enum ComponentType {
  INPUT_SWITCH = 'INPUT',
  OUTPUT_LED = 'OUTPUT',
  NOT = 'NOT',
  AND = 'AND',
  OR = 'OR',
  NAND = 'NAND',
  NOR = 'NOR',
  XOR = 'XOR',
  HEX_DISPLAY = 'HEX'
}

export interface Point {
  x: number;
  y: number;
}

// A connection point on a component
export interface Port {
  id: string; // generated ID for internal tracking if needed
  type: 'input' | 'output';
  relativePos: Point;
  label?: string;
}

// The definition of how a component behaves and looks
export interface ComponentDef {
  type: ComponentType;
  label: string;
  width: number; // in grid units
  height: number; // in grid units
  inputs: number;
  outputs: number;
  description: string;
}

// An instance of a component on the canvas
export interface CircuitComponent {
  id: string;
  type: ComponentType;
  x: number;
  y: number;
  inputValues: boolean[];
  outputValues: boolean[];
}

// A connection between two ports
export interface Wire {
  id: string;
  fromCompId: string;
  fromPortIndex: number;
  toCompId: string;
  toPortIndex: number;
  state: boolean;
}

// Logic Strategy Function Type
export type LogicEvaluator = (inputs: boolean[], currentOutputs: boolean[]) => boolean[];

export interface CircuitState {
  components: CircuitComponent[];
  wires: Wire[];
  tick: number;
}

import { CircuitComponent, Wire, ComponentType, LogicEvaluator } from '../types';

/**
 * Logic Strategies Registry (OCP - Open/Closed Principle)
 * Define behavior for each component type here.
 */
const LOGIC_STRATEGIES: Record<ComponentType, LogicEvaluator> = {
  [ComponentType.INPUT_SWITCH]: (_, currentOutputs) => currentOutputs, // State persists until toggled by user

  [ComponentType.OUTPUT_LED]: () => [],
  [ComponentType.HEX_DISPLAY]: () => [],

  [ComponentType.NOT]:  (inputs) => [!inputs[0]],
  [ComponentType.AND]:  (inputs) => [inputs[0] && inputs[1]],
  [ComponentType.OR]:   (inputs) => [inputs[0] || inputs[1]],
  [ComponentType.NAND]: (inputs) => [!(inputs[0] && inputs[1])],
  [ComponentType.NOR]:  (inputs) => [!(inputs[0] || inputs[1])],
  [ComponentType.XOR]:  (inputs) => [(!!inputs[0]) !== (!!inputs[1])],
};

/**
 * Executes one discrete step of the simulation.
 * Uses Double Buffering to ensure synchronous updates.
 */
export const stepSimulation = (
  currentComponents: CircuitComponent[],
  wires: Wire[]
): { components: CircuitComponent[], wires: Wire[] } => {

  // 1. Prepare Next State Buffer (Deep Copy)
  const nextComponents = currentComponents.map(c => ({
    ...c,
    inputValues: [...c.inputValues],
    outputValues: [...c.outputValues]
  }));

  const prevCompMap = new Map(currentComponents.map(c => [c.id, c]));
  const nextCompMap = new Map(nextComponents.map(c => [c.id, c]));

  // 2. Clear Inputs (They are transient)
  for (const comp of nextComponents) {
    comp.inputValues.fill(false);
  }

  // 3. Propagate Signals (Wired-OR Logic)
  for (const wire of wires) {
    const sourceComp = prevCompMap.get(wire.fromCompId);
    const destComp = nextCompMap.get(wire.toCompId);

    if (sourceComp && destComp) {
      if (sourceComp.outputValues[wire.fromPortIndex]) {
        destComp.inputValues[wire.toPortIndex] = true;
      }
    }
  }

  // 4. Evaluate Logic Gates
  for (const comp of nextComponents) {
    const strategy = LOGIC_STRATEGIES[comp.type];
    if (strategy) {
      comp.outputValues = strategy(comp.inputValues, comp.outputValues);
    }
  }

  // 5. Update Wire States for Visualization
  const nextWires = wires.map(w => {
    const sourceComp = nextCompMap.get(w.fromCompId);
    return {
      ...w,
      state: sourceComp ? sourceComp.outputValues[w.fromPortIndex] : false
    };
  });

  return { components: nextComponents, wires: nextWires };
};

import React, { useRef, useEffect } from 'react';
import p5Types from 'p5';
import { ComponentType, CircuitComponent, Wire, Point } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, THEME } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';

declare global {
  interface Window { p5: any; }
}

interface LogicCanvasProps {
  tool: 'SELECT' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number; 
  pendingDrop?: { type: ComponentType, x: number, y: number } | null;
  onPendingDropHandled?: () => void;
}

interface ViewportState {
  x: number;
  y: number;
  zoom: number;
}

const LogicCanvas: React.FC<LogicCanvasProps> = ({ tool, isPlaying, tickSpeedMs, pendingDrop, onPendingDropHandled }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  // -- State Refs (Mutation for Performance) --
  const componentsRef = useRef<CircuitComponent[]>([]);
  const wiresRef = useRef<Wire[]>([]);

  const tickSpeedRef = useRef(tickSpeedMs);
  const isPlayingRef = useRef(isPlaying);
  const toolRef = useRef(tool);

  useEffect(() => { tickSpeedRef.current = tickSpeedMs; }, [tickSpeedMs]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { toolRef.current = tool; }, [tool]);

  // -- Viewport --
  const viewportRef = useRef<ViewportState>({ x: 0, y: 0, zoom: 1.5 });

  // -- Interaction --
  const draggingCompId = useRef<string | null>(null);
  const isDragging = useRef<boolean>(false);
  const isPanning = useRef<boolean>(false);
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output' } | null>(null);
  const dragOffset = useRef<Point>({ x: 0, y: 0 });
  const hoveredPort = useRef<{ compId: string, portIndex: number, type: 'input'|'output', pos: Point } | null>(null);

  const accumulatorRef = useRef<number>(0);

  // -- Coordinate Utils --
  const screenToWorld = (sx: number, sy: number): Point => ({
    x: (sx - viewportRef.current.x) / viewportRef.current.zoom,
    y: (sy - viewportRef.current.y) / viewportRef.current.zoom
  });

  const worldToScreen = (wx: number, wy: number): Point => ({
    x: wx * viewportRef.current.zoom + viewportRef.current.x,
    y: wy * viewportRef.current.zoom + viewportRef.current.y
  });

  const snapToGrid = (val: number) => Math.round(val / GRID_SIZE) * GRID_SIZE;

  // -- Component Management --
  const addComponent = (type: ComponentType, screenX: number, screenY: number) => {
    const worldPos = screenToWorld(screenX, screenY);
    const def = COMPONENT_DEFINITIONS[type];

    // Center the component on the mouse
    const compW = def.width * GRID_SIZE;
    const compH = def.height * GRID_SIZE;
    const snapX = snapToGrid(worldPos.x - compW / 2);
    const snapY = snapToGrid(worldPos.y - compH / 2);

    const newComp: CircuitComponent = {
      id: crypto.randomUUID(),
      type: type,
      x: snapX,
      y: snapY,
      inputValues: new Array(def.inputs).fill(false),
      outputValues: new Array(def.outputs).fill(false)
    };
    componentsRef.current.push(newComp);
  };

  useEffect(() => {
    if (pendingDrop) {
      addComponent(pendingDrop.type, pendingDrop.x, pendingDrop.y);
      if (onPendingDropHandled) onPendingDropHandled();
    }
  }, [pendingDrop, onPendingDropHandled]);

  // -- Drag & Drop Handlers --
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const type = e.dataTransfer.getData('application/react-logic-sim') as ComponentType;
    if (type && containerRef.current && COMPONENT_DEFINITIONS[type]) {
      const rect = containerRef.current.getBoundingClientRect();
      addComponent(type, e.clientX - rect.left, e.clientY - rect.top);
    }
  };

  // -- P5 Logic --
  useEffect(() => {
    if (!containerRef.current || !window.p5) return;
    if (p5InstanceRef.current) p5InstanceRef.current.remove();

    const sketch = (p: p5Types) => {

      p.setup = () => {
        p.createCanvas(containerRef.current!.clientWidth, containerRef.current!.clientHeight);
        p.frameRate(60);
        p.strokeCap(p.ROUND);
        p.strokeJoin(p.ROUND);
      };

      p.windowResized = () => {
        if(containerRef.current) {
          p.resizeCanvas(containerRef.current.clientWidth, containerRef.current.clientHeight);
        }
      };

      p.draw = () => {
        p.background(THEME.bg);

        // -- Sim Step --
        if (isPlayingRef.current) {
          accumulatorRef.current += p.deltaTime;
          const cap = 200; // Cap lag
          if (accumulatorRef.current > cap) accumulatorRef.current = cap;

          const speed = tickSpeedRef.current;
          while (accumulatorRef.current >= speed) {
            const result = stepSimulation(componentsRef.current, wiresRef.current);
            componentsRef.current = result.components;
            wiresRef.current = result.wires;
            accumulatorRef.current -= speed;
          }
        } else {
          accumulatorRef.current = 0;
        }

        p.push();
        p.translate(viewportRef.current.x, viewportRef.current.y);
        p.scale(viewportRef.current.zoom);

        // -- Draw Grid (Dots) --
        drawGrid(p);

        // -- Draw Wires --
        wiresRef.current.forEach(wire => drawWire(p, wire));

        // -- Draw Wiring Temp Line --
        if (wiringStart.current) {
          const startPos = getAbsolutePortPos(wiringStart.current.compId, wiringStart.current.portIndex, wiringStart.current.type);
          const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

          if (startPos) {
            drawConnectionCurve(p, startPos, mouseWorld, false);
          }
        }

        // -- Draw Components --
        componentsRef.current.forEach(comp => drawComponent(p, comp));

        // -- Draw Hover Highlights --
        updateHoveredPort(p);
        if (hoveredPort.current) {
          p.noFill();
          p.stroke(THEME.portHover);
          p.strokeWeight(2);
          p.circle(hoveredPort.current.pos.x, hoveredPort.current.pos.y, 8);
        }

        p.pop();
      };

      // --- Rendering Helpers ---

      const drawGrid = (p: p5Types) => {
        const { x, y, zoom } = viewportRef.current;
        const visibleL = -x / zoom;
        const visibleT = -y / zoom;
        const visibleR = (p.width - x) / zoom;
        const visibleB = (p.height - y) / zoom;

        p.stroke(THEME.grid);
        p.strokeWeight(2 / zoom); // Keep dots constant size visually

        const startX = Math.floor(visibleL / GRID_SIZE) * GRID_SIZE;
        const endX = Math.ceil(visibleR / GRID_SIZE) * GRID_SIZE;
        const startY = Math.floor(visibleT / GRID_SIZE) * GRID_SIZE;
        const endY = Math.ceil(visibleB / GRID_SIZE) * GRID_SIZE;

        for (let gx = startX; gx <= endX; gx += GRID_SIZE) {
          for (let gy = startY; gy <= endY; gy += GRID_SIZE) {
            p.point(gx, gy);
          }
        }
      };

      const drawConnectionCurve = (p: p5Types, start: Point, end: Point, state: boolean) => {
        p.stroke(state ? THEME.wireOn : THEME.wireOff);
        p.strokeWeight(state ? 2.5 : 1.5);
        p.noFill();

        const dist = Math.abs(end.x - start.x);
        const controlDist = Math.max(dist * 0.5, 30); // Dynamic control points for S-curve

        p.bezier(
          start.x, start.y,
          start.x + controlDist, start.y,
          end.x - controlDist, end.y,
          end.x, end.y
        );
      };

      const drawWire = (p: p5Types, wire: Wire) => {
        const start = getAbsolutePortPos(wire.fromCompId, wire.fromPortIndex, 'output');
        const end = getAbsolutePortPos(wire.toCompId, wire.toPortIndex, 'input');
        if (start && end) {
          drawConnectionCurve(p, start, end, wire.state);
        }
      };

      const drawComponent = (p: p5Types, comp: CircuitComponent) => {
        const def = COMPONENT_DEFINITIONS[comp.type];
        const w = def.width * GRID_SIZE;
        const h = def.height * GRID_SIZE;

        p.push();
        p.translate(comp.x, comp.y);

        // Component Body Style
        p.fill(THEME.componentFill);
        p.stroke(THEME.componentStroke);
        p.strokeWeight(2);

        // Draw ANSI Symbol
        switch (comp.type) {
          case ComponentType.AND:
          case ComponentType.NAND:
            p.beginShape();
            p.vertex(0, 0);
            p.vertex(w * 0.5, 0);
            (p as any).arc(w * 0.5, h * 0.5, w, h, -p.HALF_PI, p.HALF_PI);
            p.vertex(0, h);
            p.endShape(p.CLOSE);
            if (comp.type === ComponentType.NAND) bubble(p, w + 4, h / 2);
            break;

          case ComponentType.OR:
          case ComponentType.NOR:
            p.beginShape();
            p.vertex(0, 0);
            (p as any).bezierVertex(w * 0.2, h * 0.2, w * 0.2, h * 0.8, 0, h);
            (p as any).bezierVertex(w * 0.6, h, w, h * 0.5, w, h * 0.5);
            (p as any).bezierVertex(w, h * 0.5, w * 0.6, 0, 0, 0);
            p.endShape(p.CLOSE);
            if (comp.type === ComponentType.NOR) bubble(p, w + 4, h / 2);
            break;

          case ComponentType.XOR:
            // Input shield curve
            p.noFill();
            p.strokeWeight(2);
            p.beginShape();
            p.vertex(-5, 0);
            (p as any).bezierVertex(w * 0.2 - 5, h * 0.2, w * 0.2 - 5, h * 0.8, -5, h);
            p.endShape();
            // Main body
            p.fill(THEME.componentFill);
            p.beginShape();
            p.vertex(0, 0);
            (p as any).bezierVertex(w * 0.2, h * 0.2, w * 0.2, h * 0.8, 0, h);
            (p as any).bezierVertex(w * 0.6, h, w, h * 0.5, w, h * 0.5);
            (p as any).bezierVertex(w, h * 0.5, w * 0.6, 0, 0, 0);
            p.endShape(p.CLOSE);
            break;

          case ComponentType.NOT:
            p.triangle(0, 0, 0, h, w, h / 2);
            bubble(p, w + 4, h / 2);
            break;

          case ComponentType.INPUT_SWITCH:
            const isOn = comp.outputValues[0];
            p.stroke(isOn ? THEME.wireOn : THEME.componentStroke);
            p.fill(isOn ? THEME.wireOn : THEME.componentFill);
            p.rect(0, 0, w, h, 4);
            p.noStroke();
            p.fill(isOn ? '#fff' : '#64748b');
            p.textAlign(p.CENTER, p.CENTER);
            p.textSize(10);
            p.text(isOn ? "ON" : "OFF", w/2, h/2);
            break;

          case ComponentType.OUTPUT_LED:
             const isLit = comp.inputValues[0];
             p.stroke(THEME.componentStroke);
             p.fill(isLit ? THEME.wireOn : '#334155');
             p.circle(w/2, h/2, Math.min(w,h) - 4);
             if (isLit) {
               p.noStroke();
               p.fill(255, 255, 255, 100);
               p.circle(w/2 - 2, h/2 - 2, 4); // Shine
             }
             break;

          case ComponentType.HEX_DISPLAY:
             p.fill('#0f172a');
             p.rect(0, 0, w, h, 2);
             p.fill('#ef4444');
             p.textAlign(p.CENTER, p.CENTER);
             p.textSize(24);
             p.textStyle(p.BOLD);
             let val = 0;
             if(comp.inputValues[0]) val += 1;
             if(comp.inputValues[1]) val += 2;
             if(comp.inputValues[2]) val += 4;
             if(comp.inputValues[3]) val += 8;
             p.text(val.toString(16).toUpperCase(), w/2, h/2);
             p.textStyle(p.NORMAL);
             break;

          default:
            p.rect(0, 0, w, h, 4);
            p.noStroke();
            p.fill(THEME.text);
            p.textSize(9);
            p.text(def.label, w/2, h/2);
        }

        // Draw Ports
        p.stroke(THEME.componentStroke);
        p.strokeWeight(1);
        p.fill(THEME.portBase);

        for (let i = 0; i < def.inputs; i++) {
          const py = (i + 1) * (h / (def.inputs + 1));
          p.line(0, py, -5, py); // Leg
          p.circle(-5, py, 4);   // Node
        }
        for (let i = 0; i < def.outputs; i++) {
          const py = (i + 1) * (h / (def.outputs + 1));
          const offset = (comp.type === ComponentType.NOT || comp.type === ComponentType.NAND || comp.type === ComponentType.NOR) ? 4 : 0;
          p.line(w + offset, py, w + offset + 5, py); // Leg
          p.circle(w + offset + 5, py, 4); // Node
        }

        p.pop();
      };

      const bubble = (p: p5Types, x: number, y: number) => {
        p.fill(THEME.componentFill);
        p.stroke(THEME.componentStroke);
        p.circle(x, y, 6);
      };

      // --- Interaction Helpers ---

      const getAbsolutePortPos = (compId: string, index: number, type: 'input' | 'output'): Point | null => {
        const comp = componentsRef.current.find(c => c.id === compId);
        if (!comp) return null;
        const def = COMPONENT_DEFINITIONS[comp.type];
        const w = def.width * GRID_SIZE;
        const h = def.height * GRID_SIZE;
        const yStep = h / ((type === 'input' ? def.inputs : def.outputs) + 1);

        let x = type === 'input' ? comp.x - 5 : comp.x + w + 5;
        // Adjust for bubbles
        if (type === 'output' && (comp.type === ComponentType.NOT || comp.type === ComponentType.NAND || comp.type === ComponentType.NOR)) {
           x += 4;
        }

        return { x, y: comp.y + ((index + 1) * yStep) };
      };

      const updateHoveredPort = (p: p5Types) => {
        const m = screenToWorld(p.mouseX, p.mouseY);
        hoveredPort.current = null;
        const HIT = 8;

        for (const comp of componentsRef.current) {
          const def = COMPONENT_DEFINITIONS[comp.type];

          for (let i = 0; i < def.inputs; i++) {
            const pos = getAbsolutePortPos(comp.id, i, 'input');
            if (pos && p.dist(m.x, m.y, pos.x, pos.y) < HIT) {
              hoveredPort.current = { compId: comp.id, portIndex: i, type: 'input', pos };
              return;
            }
          }
          for (let i = 0; i < def.outputs; i++) {
            const pos = getAbsolutePortPos(comp.id, i, 'output');
            if (pos && p.dist(m.x, m.y, pos.x, pos.y) < HIT) {
              hoveredPort.current = { compId: comp.id, portIndex: i, type: 'output', pos };
              return;
            }
          }
        }
      };

      const getHoveredComponent = (wx: number, wy: number): string | null => {
        for (let i = componentsRef.current.length - 1; i >= 0; i--) {
          const comp = componentsRef.current[i];
          const def = COMPONENT_DEFINITIONS[comp.type];
          if (wx >= comp.x && wx <= comp.x + (def.width * GRID_SIZE) &&
              wy >= comp.y && wy <= comp.y + (def.height * GRID_SIZE)) {
            return comp.id;
          }
        }
        return null;
      };

      // --- Interaction Events ---

      p.mouseWheel = (e: any) => {
        const zoomSpeed = 0.001;
        const newZoom = Math.min(Math.max(viewportRef.current.zoom * Math.exp(-e.delta * zoomSpeed), 0.5), 4);

        // Zoom towards mouse
        const wx = (p.mouseX - viewportRef.current.x) / viewportRef.current.zoom;
        const wy = (p.mouseY - viewportRef.current.y) / viewportRef.current.zoom;

        viewportRef.current.x = p.mouseX - wx * newZoom;
        viewportRef.current.y = p.mouseY - wy * newZoom;
        viewportRef.current.zoom = newZoom;
        return false;
      };

      p.mousePressed = () => {
        if (p.mouseX < 0 || p.mouseX > p.width || p.mouseY < 0 || p.mouseY > p.height) return;

        const m = screenToWorld(p.mouseX, p.mouseY);

        // 1. Port Interaction (Wiring)
        updateHoveredPort(p);
        if (hoveredPort.current) {
          wiringStart.current = { 
            compId: hoveredPort.current.compId, 
            portIndex: hoveredPort.current.portIndex, 
            type: hoveredPort.current.type 
          };
          return;
        }

        // 2. Component Interaction (Drag/Toggle/Delete)
        const compId = getHoveredComponent(m.x, m.y);
        if (compId) {
          if (toolRef.current === 'DELETE') {
             componentsRef.current = componentsRef.current.filter(c => c.id !== compId);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== compId && w.toCompId !== compId);
             return;
          }

          draggingCompId.current = compId;
          const comp = componentsRef.current.find(c => c.id === compId)!;
          dragOffset.current = { x: m.x - comp.x, y: m.y - comp.y };
          isDragging.current = false; // Will set to true on drag
          return;
        }

        // 3. Pan
        isPanning.current = true;
      };

      p.mouseDragged = () => {
        const m = screenToWorld(p.mouseX, p.mouseY);

        if (draggingCompId.current) {
          isDragging.current = true;
          const comp = componentsRef.current.find(c => c.id === draggingCompId.current);
          if (comp) {
            comp.x = snapToGrid(m.x - dragOffset.current.x);
            comp.y = snapToGrid(m.y - dragOffset.current.y);
          }
        } else if (isPanning.current) {
          viewportRef.current.x += p.mouseX - p.pmouseX;
          viewportRef.current.y += p.mouseY - p.pmouseY;
        }
      };

      p.mouseReleased = () => {
        // Component Click (Toggle)
        if (draggingCompId.current && !isDragging.current) {
          const comp = componentsRef.current.find(c => c.id === draggingCompId.current);
          if (comp && comp.type === ComponentType.INPUT_SWITCH) {
            comp.outputValues[0] = !comp.outputValues[0];
          }
        }

        // Complete Wiring
        if (wiringStart.current) {
          updateHoveredPort(p);
          if (hoveredPort.current) {
            const start = wiringStart.current;
            const end = hoveredPort.current;

            // Valid connection check: Different components, Output -> Input
            if (start.compId !== end.compId && start.type !== end.type) {
               const src = start.type === 'output' ? start : end;
               const dst = start.type === 'input' ? start : end;

               // Avoid duplicates
               const exists = wiresRef.current.some(w => 
                 w.toCompId === dst.compId && w.toPortIndex === dst.portIndex
               );

               if (!exists) {
                 wiresRef.current.push({
                   id: crypto.randomUUID(),
                   fromCompId: src.compId,
                   fromPortIndex: src.portIndex,
                   toCompId: dst.compId,
                   toPortIndex: dst.portIndex,
                   state: false
                 });
               }
            }
          }
        }

        // Reset
        draggingCompId.current = null;
        isDragging.current = false;
        isPanning.current = false;
        wiringStart.current = null;
      };
    };

    p5InstanceRef.current = new (window as any).p5(sketch, containerRef.current);
    return () => { p5InstanceRef.current?.remove(); };
  }, []);

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full cursor-crosshair overflow-hidden touch-none" 
      onDragOver={handleDragOver}
      onDrop={handleDrop}
    />
  );
};

export default LogicCanvas;

import React from 'react';
import { ComponentType } from '../types';
import { COMPONENT_DEFINITIONS } from '../constants';

interface SidebarProps {
  selectedTool: 'SELECT' | 'DELETE';
  onSelectTool: (t: 'SELECT' | 'DELETE') => void;
  onTouchStartItem?: (type: ComponentType, e: React.TouchEvent) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ selectedTool, onSelectTool, onTouchStartItem }) => {
  const categories = [
    { title: 'I/O', items: [ComponentType.INPUT_SWITCH, ComponentType.OUTPUT_LED, ComponentType.HEX_DISPLAY] },
    { title: 'Gates', items: [ComponentType.AND, ComponentType.OR, ComponentType.NOT, ComponentType.NAND, ComponentType.NOR, ComponentType.XOR] }
  ];

  const handleDragStart = (e: React.DragEvent, type: ComponentType) => {
    e.dataTransfer.setData('application/react-logic-sim', type);
    e.dataTransfer.effectAllowed = 'copy';
  };

  return (
    <div className="w-60 bg-white border-r border-slate-200 flex flex-col h-full shadow-md z-10 select-none">
      <div className="p-5 border-b border-slate-100">
        <h1 className="text-xl font-bold text-slate-800 tracking-tight flex items-center gap-2">
          <span className="w-3 h-3 bg-blue-600 rounded-full"></span>
          LogicFlow
        </h1>
        <p className="text-[10px] text-slate-400 font-mono mt-1 ml-5">ENGINEERING SIM</p>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6">

        {/* Tools */}
        <div className="flex gap-2 p-1 bg-slate-100 rounded-lg">
          <button
            onClick={() => onSelectTool('SELECT')}
            className={`flex-1 py-1.5 text-xs font-semibold rounded-md transition-all ${
              selectedTool === 'SELECT' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            SELECT
          </button>
          <button
            onClick={() => onSelectTool('DELETE')}
            className={`flex-1 py-1.5 text-xs font-semibold rounded-md transition-all ${
              selectedTool === 'DELETE' ? 'bg-white text-red-500 shadow-sm' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            DELETE
          </button>
        </div>

        {/* Library */}
        {categories.map(cat => (
          <div key={cat.title}>
            <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 pl-1">{cat.title}</h3>
            <div className="grid grid-cols-2 gap-2">
              {cat.items.map(type => {
                const def = COMPONENT_DEFINITIONS[type];
                return (
                  <div
                    key={type}
                    draggable={true}
                    onDragStart={(e) => handleDragStart(e, type)}
                    onTouchStart={(e) => onTouchStartItem && onTouchStartItem(type, e)}
                    className="group flex flex-col items-center justify-center p-3 rounded-lg border border-slate-100 bg-slate-50 hover:bg-white hover:border-blue-400 hover:shadow-md transition-all cursor-grab active:cursor-grabbing"
                  >
                    <div className="mb-2 text-slate-700 font-bold text-xs group-hover:text-blue-600">
                      {def.label}
                    </div>
                    {/* Tiny visual representation */}
                    <div className="w-full h-1 bg-slate-200 rounded-full overflow-hidden">
                      <div className="h-full bg-slate-300 w-2/3 group-hover:bg-blue-400"></div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        ))}
      </div>

      <div className="p-4 bg-slate-50 border-t border-slate-200 text-[10px] text-slate-400 text-center">
        v2.0.0 • React + P5.js
      </div>
    </div>
  );
};

export default Sidebar;

import React, { useState, useRef, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas from './components/LogicCanvas';
import { ComponentType } from './types';
import { COMPONENT_DEFINITIONS } from './constants';

const App: React.FC = () => {
  const [selectedTool, setSelectedTool] = useState<'SELECT' | 'DELETE'>('SELECT');
  const [isPlaying, setIsPlaying] = useState(true);
  const [tickSpeed, setTickSpeed] = useState(20); 

  const [draggedType, setDraggedType] = useState<ComponentType | null>(null);
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);
  const [pendingDrop, setPendingDrop] = useState<{type: ComponentType, x: number, y: number} | null>(null);

  const canvasWrapperRef = useRef<HTMLDivElement>(null);

  // Mobile/Touch Dragging Logic
  const handleTouchStartItem = (type: ComponentType, e: React.TouchEvent) => {
    const touch = e.touches[0];
    setDraggedType(type);
    setDragPos({ x: touch.clientX, y: touch.clientY });
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedType) {
        e.preventDefault(); 
        const touch = e.touches[0];
        setDragPos({ x: touch.clientX, y: touch.clientY });
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      if (draggedType && dragPos && canvasWrapperRef.current) {
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          dragPos.x >= rect.left &&
          dragPos.x <= rect.right &&
          dragPos.y >= rect.top &&
          dragPos.y <= rect.bottom
        ) {
          setPendingDrop({ 
            type: draggedType, 
            x: dragPos.x - rect.left, 
            y: dragPos.y - rect.top 
          });
        }
      }
      setDraggedType(null);
      setDragPos(null);
    };

    if (draggedType) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }
    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedType, dragPos]);

  return (
    <div className="flex h-screen w-screen bg-slate-100 text-slate-800 font-sans overflow-hidden">

      <Sidebar 
        selectedTool={selectedTool} 
        onSelectTool={setSelectedTool}
        onTouchStartItem={handleTouchStartItem}
      />

      <main className="flex-1 flex flex-col relative bg-slate-50">

        {/* Floating Control Bar */}
        <div className="absolute top-4 left-1/2 -translate-x-1/2 h-10 bg-white/90 backdrop-blur-sm shadow-md rounded-full flex items-center px-4 gap-4 z-20 border border-slate-200">

           <button 
             onClick={() => setIsPlaying(!isPlaying)}
             className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold transition-all ${
               isPlaying ? 'bg-green-100 text-green-700' : 'bg-orange-100 text-orange-700'
             }`}
           >
             <span className={`w-2 h-2 rounded-full ${isPlaying ? 'bg-green-500' : 'bg-orange-500'}`}></span>
             {isPlaying ? 'RUNNING' : 'PAUSED'}
           </button>

           <div className="w-px h-4 bg-slate-200"></div>

           <div className="flex items-center gap-2">
            <span className="text-[10px] font-bold text-slate-400">SPEED</span>
            <input 
              type="range" 
              min="5" 
              max="200" 
              step="5"
              value={tickSpeed} 
              onChange={(e) => setTickSpeed(Number(e.target.value))}
              className="w-20 h-1 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-slate-800" 
            />
           </div>

           <div className="w-px h-4 bg-slate-200"></div>

           <button 
              onClick={() => window.location.reload()}
              className="text-xs font-bold text-slate-400 hover:text-red-500 transition-colors"
            >
              RESET
            </button>
        </div>

        <div className="flex-1 relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            onPendingDropHandled={() => setPendingDrop(null)}
          />
        </div>

        {/* Touch Drag Ghost */}
        {draggedType && dragPos && (
          <div 
            className="fixed pointer-events-none z-50 p-2 bg-white rounded-md shadow-xl border border-blue-500 opacity-90"
            style={{ left: dragPos.x, top: dragPos.y, transform: 'translate(-50%, -50%)' }}
          >
            <span className="text-xs font-bold text-blue-700">
              {COMPONENT_DEFINITIONS[draggedType].label}
            </span>
          </div>
        )}

      </main>
    </div>
  );
};

export default App;
